    let mut h = queue();
    assert_eq!(list(&mut h), json!({}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "1", "b": ""}}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "2", "A": "x"}}));
    assert_eq!(list(&mut h), json!({"a": "2", "b": "", "A": "x"}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["a", "missing"]}));
    assert_eq!(list(&mut h), json!({"b": "", "A": "x"}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {}}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": []}));
    assert_eq!(list(&mut h), json!({"b": "", "A": "x"}));
}

#[test]
fn invalid_tags_are_parameter_errors() {
    let mut h = queue();
    let long_key = "k".repeat(129);
    let long_value = "v".repeat(257);
    for tags in [
        json!({"bad key": "v"}),
        json!({"": "v"}),
        json!({long_key: "v"}),
        json!({"k": 1}),
        json!({"k": null}),
        json!({"k": long_value}),
    ] {
        assert_eq!(tag(&mut h, tags.clone())["error"]["code"], "InvalidParameterValue", "{tags}");
    }
    assert_eq!(tag(&mut h, json!([]))["error"]["code"], "InvalidParameterValue");
    for keys in [json!(["bad key"]), json!([1]), json!("a"), json!([""])] {
        let code = h.err(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": keys}));
        assert_eq!(code, "InvalidParameterValue", "{keys}");
    }
    assert_eq!(list(&mut h), json!({}));
}

#[test]
fn value_limits_are_inclusive_and_counted_in_bytes() {
    let mut h = queue();
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "v".repeat(256), "b": "é".repeat(128)}}));
    let over = tag(&mut h, json!({"c": "é".repeat(129)}));
    assert_eq!(over["error"]["code"], "InvalidParameterValue");
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"k".repeat(128): ""}}));
}

#[test]
fn missing_parameters_and_unknown_queue() {
    let mut h = queue();
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "UntagQueue", "Tags": {}})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "ListQueueTags"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "nope", "Tags": {}})), "QueueDoesNotExist");
    assert_eq!(h.err(json!({"Command": "UntagQueue", "QueueName": "nope", "TagKeys": []})), "QueueDoesNotExist");
    assert_eq!(h.err(json!({"Command": "ListQueueTags", "QueueName": "nope"})), "QueueDoesNotExist");
}

#[test]
fn at_most_fifty_tags() {
    let mut h = queue();
    let fifty: serde_json::Map<String, Value> = (0..50).map(|i| (format!("k{i}"), json!("v"))).collect();
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": fifty}));
    // Replacing existing keys does not add tags.
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"k0": "new"}}));
    assert_eq!(tag(&mut h, json!({"extra": "v"}))["error"]["code"], "LimitExceeded");
    // A failed command changes nothing: the replacement in the same request is not applied.
    assert_eq!(tag(&mut h, json!({"k1": "changed", "extra": "v"}))["error"]["code"], "LimitExceeded");
    let tags = list(&mut h);
    assert_eq!(tags["k1"], "v");
    assert_eq!(tags["k0"], "new");
    assert_eq!(tags.as_object().unwrap().len(), 50);
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["k0"]}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"extra": "v"}}));
}

#[test]
fn tags_are_not_attributes_and_survive_purge_but_not_delete() {
    let mut h = queue();
    let before = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "1"}}));
    assert_eq!(h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"})), before);
    // CreateQueue rule 4 ignores tags: the same attributes still succeed.
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "SendMessage", "QueueName": "q", "Body": "x"}));
    h.ok(json!({"Command": "PurgeQueue", "QueueName": "q"}));
    assert_eq!(list(&mut h), json!({"a": "1"}));
    h.ok(json!({"Command": "DeleteQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    assert_eq!(list(&mut h), json!({}));
}
