fn value_limits_are_inclusive_and_counted_in_bytes() {
    let mut h = queue();
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "v".repeat(256), "b": "é".repeat(128)}}));
    let over = tag(&mut h, json!({"c": "é".repeat(129)}));
    assert_eq!(over["error"]["code"], "InvalidParameterValue");
